TLM.f("Sancti/10-14",{"officium":"S. Callisti Papæ et Martyris","rule":["vide C4b;","Gloria"],"ruleInherited":["Prefatio=Apostolis"],"fallback":"Commune/C4b","from":{"Introitus":"Commune/C4b","Lectio":"Commune/C4b","Graduale":"Commune/C4b","GradualeP":"Commune/C4b","Tractus":"Commune/C4b","Evangelium":"Commune/C4b","Offertorium":"Commune/C4b","Communio":"Commune/C4b"},"sections":{"Introitus":[{"k":"ref","la":"Joann 21:15-17"},{"k":"text","la":"Si díligis me, Simon Petre, pasce agnos meos, pasce oves meas. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 29:2"},{"k":"text","la":"Exaltábo te, Dómine, quóniam suscepísti me, nec delectásti inimícos meos super me."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Si díligis me, Simon Petre, pasce agnos meos, pasce oves meas. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Deus, qui nos cónspicis ex nostra infirmitáte defícere: ad amórem tuum nos misericórditer per Sanctórum tuórum exémpla restáura."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Petri Apóstoli"},{"k":"ref","la":"1 Pet 5:1-4; 5:10-11"},{"k":"text","la":"Caríssimi: Senióres, qui in vobis sunt, obsécro consénior et testis Christi passiónum, qui et ejus, quæ in futúro revelánda est, glóriæ communicátor: páscite qui in vobis est gregem Dei, providéntes non coácte, sed spontánee secúndum Deum, neque turpis lucri grátia, sed voluntárie; neque ut dominántes in cleris, sed forma facti gregis ex ánimo. Et, cum apparúerit princeps pastórum, percipiétis immarcescíbilem glóriæ corónam. Deus autem omnis grátiæ, qui vocávit nos in ætérnam suam glóriam in Christo Jesu, módicum passos ipse perfíciet, confirmábit solidabítque. Ipsi glória et impérium in sǽcula sæculórum. Amen."}],"Graduale":[{"k":"ref","la":"Ps 106:32; 106:31"},{"k":"text","la":"Exáltent eum in ecclésia plebis: et in cáthedra seniórum laudent eum."},{"k":"text","la":"Confiteántur Dómino misericórdiæ ejus, et mirabília ejus fíliis hóminum.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Matt 16:18"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Matt 16:18"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam. Allelúja."},{"k":"ref","la":"Ps 44:17-18"},{"k":"text","la":"Constítues eos príncipes super omnem terram: mémores erunt nóminis tui, Dómine. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 106:32; 106:31"},{"k":"text","la":"Exáltent eum in Ecclésia plebis: et in cáthedra seniórum laudent eum."},{"k":"text","la":"Confiteántur Dómino misericórdiæ ejus; et mirabília ejus fíliis hóminum","mark":"V"},{"k":"ref","la":"Ps 39:10-11"},{"k":"text","la":"Annuntiávi justítiam tuam in ecclésia magna, ecce, lábia mea non prohibébo: Dómine, tu scisti."},{"k":"text","la":"Justítiam tuam non abscóndi in corde meo: veritátem tuam et salutáre tuum dixi.","mark":"V"},{"k":"text","la":"Non abscóndi misericórdiam tuam, et veritátem tuam a concílio multo.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 16:13-19"},{"k":"text","la":"In illo témpore: Venit Jesus in partes Cæsaréæ Philíppi, et interrogábat discípulos suos, dicens: Quem dicunt hómines esse Fílium hóminis? At illi dixérunt: Alii Joánnem Baptístam, alii autem Elíam, álii vero Jeremíam, aut unum ex prophétis. Dicit illis Jesus: Vos autem quem me esse dícitis? Respóndens Simon Petrus, dixit: Tu es Christus, Fílius Dei vivi. Respóndens autem Jesus, dixit ei: Beátus es, Simon Bar Jona: quia caro et sanguis non revelávit tibi, sed Pater meus, qui in cœlis est. Et ego dico tibi, quia tu es Petrus, et super hanc petram ædificábo Ecclésiam meam, et portæ ínferi non prævalébunt advérsus eam. Et tibi dabo claves regni cœlórum. Et quodcúmque ligáveris super terram, erit ligátum et in cœlis: et quodcúmque sólveris super terram, erit solútum et in cœlis."}],"Offertorium":[{"k":"ref","la":"Jer 1:9-10"},{"k":"text","la":"Ecce, dedi verba mea in ore tuo: ecce, constítui te super gentes et super regna, ut evéllas et déstruas, et ædífices et plantes. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Mýstica nobis, Dómine, prosit oblátio: quæ nos et a reátibus nostris expédiat, et perpétua salvatióne confírmet."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 16:18"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Quǽsumus, omnípotens Deus: ut reátus nostros múnera sacráta puríficent, et recte vivéndi nobis operéntur efféctum."},{"k":"macro","name":"Per Dominum"}]},"hr":{"470dcbf4d64e0e5a":{"t":"Iv 21, 15-17, Ps 29,1\n(Iv 21, 15-17) Ako me ljubiš, Šimune Petre, pasi janjce moje, pasi ovce moje. (Ps 29,1) Veličat ću te, Gospodine, jer si me odabrao i nisi dao da se moji neprijatelji raduju nada mnom.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Iv 21, 15-17) Ako me ljubiš, Šimune Petre, pasi janjce moje, pasi ovce moje."},"946cad3215350f3e":{"t":"<i>Pomolimo se</i>.\nBože, koji vidiš da malakšemo. zbog svoje slabosti, milosrdno nas obnovi u svojoj ljubavi po primjerima svojih svetih.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"1207c20c86be0fe4":{"t":"1 Pt 5, 1-4 i 10-11\nČitanje Poslanice bl. Petra apostola. Predragi, starješine među vama opominjem ja koji sam i sam starješina i svjedok Kristovih muka, a koji sam i dionik slave koja se ima u buduće otkriti: Pasite stado Božje koje vam je povjereno i nadgledajte ga ne silom, nego dragovoljno, kako Bog hoće; niti radi niskog dobitka, nego iz dobra srca; niti kao da gospodujete općinama, nego kao oni koji su izgled stadu od srca. I kad se javi Vrhovni Pastir, primit ćete neuveli vijenac slave. A Bog svake milosti koji vas pozva na vječnu svoju slavu u Kristu Isusu, on će vas, iza malo muke, usavršiti, okrijepiti i utvrditi. Njemu slava i vlast u vijeke vjekova. Amen."},"171509e2e2807f88":{"t":"Ps 106, 32 i 31\nNeka ga uzvisuju u narodnom zboru, neka ga hvale u vijeću staraca. Neka hvale Gospodina za dobrotu njegovu, za čudesa njegova sinovima ljudskim.\n\nMt 16, 18\n<i>Aleluja</i>, <i>aleluja</i>.\nTi si Petar–stijena, i na toj stijeni sazidat ću svoju Crkvu. <i>Aleluja</i>."},"2eaad8272860ffbe":{"t":"Mt 16, 13-19\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: Kad Isus dođe u krajeve Cezareje Filipove, upita učenike: Što govore ljudi, tko je Sin Čovječji? Oni rekoše: Jedni da je Ivan Krstitelj; drugi da je Ilija; treći opet da je Jeremija ili koji od proroka. Kaže im Isus: A vi, što vi kažete, tko sam ja? Šimun Petar prihvati i reče: Ti si Krist-Pomazanik, Sin Boga živoga. Nato Isus reče njemu: Blago tebi, Šimune, sine Jonin, jer ti to ne objavi tijelo i krv, nego Otac moj, koji je na nebesima. A ja tebi kažem: Ti si Petar-Stijena, i na toj stijeni sazidat ću Crkvu svoju. I vrata paklena neće je nadvladati. A tebi ću dati ključeve kraljevstva nebeskoga. Što god svežeš na zemlji bit će svezano i na nebu. A što god razriješiš na zemlji bit će razriješeno i na nebu."},"3bfd99647c6900a1":{"t":"Jr 1, 9-10\nEvo sam stavio svoje riječi na tvoja usta. Evo sam te danas postavio nad narodima i nad kraljevstvima, da trijebiš i obaraš, gradiš i sadiš.","v":"hodie → ∅"},"77a2847f7c3dfe61":{"t":"Koristio nam, Gospodine, otajstveni prinos, koji neka nas očisti od naše krivnje i utvrdi po stalnom spašavanju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"a937e43128eeb79a":{"t":"Mt 16, 18\nTi si Petar–stijena, i na toj stijeni sazidat ću svoju Crkvu."},"7d89a8d68954209f":{"t":"<i>Pomolimo se</i>.\nMolimo, svemogući Bože, da posvećeni darovi očiste naše krivice, pomognu nam da ispravno živimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}},"variants":{"paschal":{"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Matt 16:18"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam. Allelúja."},{"k":"ref","la":"Ps 44:17-18"},{"k":"text","la":"Constítues eos príncipes super omnem terram: mémores erunt nóminis tui, Dómine. Allelúja."}]}}});
